CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ModelAsset" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"originalFilename" TEXT NOT NULL,"sourceUrl" TEXT,"normalizedGlbUrl" TEXT,"thumbnailUrl" TEXT,"status" TEXT NOT NULL DEFAULT 'UPLOADED',"unit" TEXT NOT NULL DEFAULT 'mm',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ModelManifest" ("id" TEXT PRIMARY KEY,"modelAssetId" TEXT NOT NULL,"version" INTEGER NOT NULL,"manifestJson" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ModelManifest_modelAssetId_fkey" FOREIGN KEY ("modelAssetId") REFERENCES "ModelAsset"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "ModelManifest_modelAssetId_version_key" ON "ModelManifest"("modelAssetId","version");
CREATE TABLE "Project" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"modelAssetId" TEXT NOT NULL,"name" TEXT NOT NULL,"activeVersionId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Project_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT "Project_modelAssetId_fkey" FOREIGN KEY ("modelAssetId") REFERENCES "ModelAsset"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "ModelVersion" ("id" TEXT PRIMARY KEY,"projectId" TEXT NOT NULL,"name" TEXT NOT NULL,"configurationJson" JSONB NOT NULL,"previewUrl" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ModelVersion_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "MaterialPreset" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"category" TEXT NOT NULL,"propertiesJson" JSONB NOT NULL,"styleTags" TEXT[] NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "ComponentVariant" ("id" TEXT PRIMARY KEY,"groupId" TEXT NOT NULL,"role" TEXT NOT NULL,"name" TEXT NOT NULL,"assetUrl" TEXT NOT NULL,"compatibilityJson" JSONB NOT NULL,"metadataJson" JSONB NOT NULL);
CREATE TABLE "ManufacturingRule" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"type" TEXT NOT NULL,"severity" TEXT NOT NULL,"ruleJson" JSONB NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "Job" ("id" TEXT PRIMARY KEY,"type" TEXT NOT NULL,"status" TEXT NOT NULL,"payload" JSONB NOT NULL,"result" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
